import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { sanitizeRichText } from './sanitize';

/**
 * Outputs recorded from `sanitizeRichText` before the custom-HTML profile existed (generated by the pre-change
 * implementation over a seeded corpus). The rich text profile must stay byte-for-byte identical.
 */
describe('hk-rich-text sanitiser is unchanged', () => {
  const cases = (JSON.parse(readFileSync(new URL('./sanitize-rich.golden.json', import.meta.url), 'utf8')) as { cases: [string, string, string][] }).cases;
  it('has a corpus', () => expect(cases.length).toBeGreaterThan(500));
  it('default cap output is identical', () => {
    for (const [input, out] of cases) expect(sanitizeRichText(input)).toBe(out);
  });
  it('maxChars: 40 output is identical', () => {
    for (const [input, , small] of cases) expect(sanitizeRichText(input, { maxChars: 40 })).toBe(small);
  });
});
